def gen(rng):
    base = 'abcdefghijklmnopqrstuvwxyz'
    other = 'ABCXYZ0123.,!?-'
    def word(lo=1, hi=8):
        return ''.join(rng.choice(base + other) for _ in range(rng.randint(lo, hi)))
    def gap():
        return ' ' * rng.choice([1, 1, 1, 2, 3, 5])
    def sentence(k, lead, trail):
        s = ' ' * lead if lead else ''
        for i in range(k):
            if i:
                s += gap()
            s += word()
        return s + (' ' * trail if trail else '')
    tests = ['hello', ' a ', 'a b', 'a  b', '     x', 'x     ', '  the   quick  brown fox ', 'a    b     c', '!   ?']
    for _ in range(50):
        tests.append(sentence(rng.randint(1, 12), rng.choice([0, 0, 1, 4]), rng.choice([0, 0, 2, 6])))
    N = 10 ** 6
    big = []
    ln = 0
    while ln < N:
        w = word(1, 12) + gap()
        big.append(w)
        ln += len(w)
    s = ''.join(big)[:N]
    tests.append(s if s.strip() else 'x')
    tests.append('x' * N)
    tests.append('a' + ' ' * (N - 2) + 'b')
    tests.append(' '.join(word(1, 6) for _ in range(N // 4))[:N])
    tests.append(' ' * 1000 + 'q' + ' ' * (N - 2000) + 'r' + ' ' * 998)
    return tests
